<section class="page-heading"><div><h1>Staff &amp; Permissions</h1><p>Choose what each member of your team can access.</p></div><span class="label-chip"><?= count($staff) ?> staff accounts</span></section>
<?php if ($notice): ?><p class="notice" role="status"><?= e($notice) ?></p><?php endif; ?>
<div class="info-strip"><?= icon('info') ?><span>Changes apply immediately. Staff accounts are provisioned by your administrator.</span></div>
<?php if (!$staff): ?><section class="surface"><div class="empty-state"><?= icon('users') ?><h2>No staff accounts yet</h2><p>Ask your administrator to add staff accounts for this shop.</p></div></section><?php endif; ?>
<section class="staff-grid"><?php foreach ($staff as $member): ?><form method="post" action="<?= e(url('/staff/permissions')) ?>" class="surface staff-card" data-staff-permissions><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="staff_id" value="<?= (int)$member['id'] ?>"><header><span class="avatar"><?= e(mb_strtoupper(mb_substr($member['name'],0,1))) ?></span><div><h2><?= e($member['name']) ?></h2><p><?= e($member['email']) ?></p></div><span class="label-chip">Staff</span></header><div class="staff-permissions-list"><?php foreach (permissions() as $key=>$label): ?><label><span><?= e($label) ?></span><input type="checkbox" name="permissions[]" value="<?= e($key) ?>" <?= in_array($key,$member['permissions'],true)?'checked':'' ?>></label><?php endforeach; ?></div><footer><span role="status" aria-live="polite"></span><button class="button button-primary" type="submit">Save permissions</button></footer></form><?php endforeach; ?></section>
